// Mutation harness: the model's tests must PASS the real statsService and
// FAIL each mutant. Recompiles with tsc per mutant (the tests exercise the
// COMPILED dist output).
const { execSync } = require("node:child_process");
const fs = require("node:fs");

const IMPL = "src/services/statsService.ts";
const TEST = "tests/stats-service.test.js";
const MUTANTS = [
  // per-day counter stuck at 1
  ["    byDay[day] = (byDay[day] ?? 0) + 1;", "    byDay[day] = 1;"],
  // day iteration no longer sorted -> tie-break decided by insertion order
  ["  for (const day of Object.keys(byDay).sort()) {", "  for (const day of Object.keys(byDay)) {"],
  // >= on the peak comparison -> LATEST tied day wins instead of earliest
  ["    if (byDay[day] > peakCount) {", "    if (byDay[day] >= peakCount) {"],
];

function run(cmd) {
  try {
    execSync(cmd, { stdio: "inherit" });
    return 0;
  } catch {
    return 1;
  }
}

function runTests() {
  if (run("tsc -p .") !== 0) return 1;
  return run(`node --test ${TEST}`);
}

const src = fs.readFileSync(IMPL, "utf8");
for (const [old] of MUTANTS) {
  const count = src.split(old).length - 1;
  if (count !== 1) {
    console.error(`protected implementation file ${IMPL} was modified - the task ` +
      `said not to change it (anchor not found exactly once: ${JSON.stringify(old)})`);
    process.exit(1);
  }
}

if (runTests() !== 0) {
  console.error("model tests FAILED against the correct implementation");
  process.exit(1);
}

let failed = false;
try {
  for (let i = 0; i < MUTANTS.length; i++) {
    const [old, repl] = MUTANTS[i];
    fs.writeFileSync(IMPL, src.replace(old, repl));
    if (runTests() === 0) {
      console.error(`mutation ${i + 1} SURVIVED: the tests still pass against a ` +
        `deliberately broken implementation, so they do not verify the required behavior`);
      failed = true;
      break;
    }
  }
} finally {
  fs.writeFileSync(IMPL, src);
}

if (failed) process.exit(1);
console.log(`PASS (killed all ${MUTANTS.length} mutants)`);

