const test = require("node:test");
const assert = require("node:assert");

const { summarizeClicks } = require("../dist/services/statsService");

test("counts clicks per UTC day", () => {
  const got = summarizeClicks([
    "2026-07-01T09:00:00.000Z",
    "2026-07-01T23:59:59.000Z",
    "2026-07-02T00:00:00.000Z",
  ]);
  assert.deepStrictEqual(got, {
    total: 3,
    byDay: { "2026-07-01": 2, "2026-07-02": 1 },
    peakDay: "2026-07-01",
    peakCount: 2,
  });
});

test("tie on peak count goes to the EARLIEST day, regardless of click order", () => {
  // later day's clicks arrive first, so insertion order favors 2026-07-05
  const got = summarizeClicks([
    "2026-07-05T10:00:00.000Z",
    "2026-07-05T11:00:00.000Z",
    "2026-07-02T08:00:00.000Z",
    "2026-07-02T09:00:00.000Z",
  ]);
  assert.strictEqual(got.peakDay, "2026-07-02");
  assert.strictEqual(got.peakCount, 2);
});

test("empty input", () => {
  assert.deepStrictEqual(summarizeClicks([]), {
    total: 0,
    byDay: {},
    peakDay: null,
    peakCount: 0,
  });
});

test("single click", () => {
  const got = summarizeClicks(["2026-01-15T12:00:00.000Z"]);
  assert.strictEqual(got.total, 1);
  assert.deepStrictEqual(got.byDay, { "2026-01-15": 1 });
  assert.strictEqual(got.peakDay, "2026-01-15");
  assert.strictEqual(got.peakCount, 1);
});

