const test = require("node:test");
const assert = require("node:assert");

const { summarizeClicks } = require("../dist/services/statsService");

test("returns an object", () => {
  assert.strictEqual(typeof summarizeClicks([]), "object");
});

test("total matches input length", () => {
  assert.strictEqual(summarizeClicks(["2026-07-01T09:00:00.000Z"]).total, 1);
});

test("empty gives null peak", () => {
  assert.strictEqual(summarizeClicks([]).peakDay, null);
});

test("peak day is one of the clicked days", () => {
  const got = summarizeClicks(["2026-07-01T09:00:00.000Z", "2026-07-02T09:00:00.000Z"]);
  assert.ok(["2026-07-01", "2026-07-02"].includes(got.peakDay));
});
